async function action(name,id,element) {
  const p=project();
  switch(name) {
    case 'project':currentId=id;comparison=null;reviewSession=null;clearTimeout(reviewTimer);rfiFilter='All';tab='Overview';localStorage.setItem('bigdelta-project',id);render();break;
    case 'tab':clearTimeout(reviewTimer);tab=id;render();break;
    case 'upload':uploadDialog();break;
    case 'revision':uploadDialog(id);break;
    case 'template':templateDialog();break;
    case 'section-add': {
      modal('Add report section',field('Section title','name','','text','required maxlength="120"')+select('Position in report','position',[...p.sections.map((s,i)=>[String(i),`Before ${s.name}`]),[String(p.sections.length),'At the end']],String(p.sections.length)),data=>mutate('section_add',{name:data.name,position:Number(data.position)},'Report section added.'),'Add section');break;
    }
    case 'section-delete': {
      const s=p.sections.find(s=>s.id===id),others=p.sections.filter(s=>s.id!==id);
      if(!others.length)return toast('Keep at least one report section. Add another section first.');
      modal('Delete report section',`<p>Delete <b>${esc(s.name)}</b> from this report structure?</p>`+(s.document_ids.length?`<div class="notice">This section contains ${s.document_ids.length} document(s). Choose another section to receive them. Files and revision history will be preserved.</div>`+select('Move documents to','destination_id',[['','Choose a destination'],...others.map(s=>[s.id,s.name])],'','required'):'<p class="help">This section is empty. Previously compiled packages keep their original contents.</p>'),data=>mutate('section_delete',{section_id:id,destination_id:data.destination_id},'Report section deleted.'),'Delete section');break;
    }
    case 'section-rename': {
      const s=p.sections.find(s=>s.id===id);
      modal('Rename report section',field('Section title','name',s.name,'text','required maxlength="120"'),data=>mutate('section',{...data,section_id:id},'Section renamed.'));break;
    }
    case 'section-up':case 'section-down': {
      const position=p.sections.findIndex(s=>s.id===id)+(name==='section-up'?-1:1);
      if(position>=0&&position<p.sections.length)await mutate('section',{section_id:id,position},'Report section moved.');break;
    }
    case 'section-position': {
      const position=p.sections.findIndex(s=>s.id===id);
      modal('Move report section',select('Position in report','position',p.sections.map((s,i)=>[String(i),`${i+1} — ${s.name}`]),String(position)),data=>mutate('section',{section_id:id,position:Number(data.position)},'Report section moved.'));break;
    }
    case 'compile':compileDialog();break;
    case 'cover-edit':coverDialog();break;
    case 'package-save':await savePackage(id,element);break;
    case 'new-change':changeDialog();break;
    case 'record':recordDialog();break;
    case 'resolve':modal('Record impact resolution',`<p>Confirm the affected document has been updated or reviewed. This records the resolution against its latest uploaded revision.</p>`+textarea('Resolution / review note','note','','required maxlength="4000"'),data=>mutate('resolve',{...data,change_id:id,document_id:element.dataset.document},'Impact resolution recorded.'));break;
    case 'progress':modal('Set current project phase',select('Phase','phase',phases.map(x=>[x,x]),p.phase)+`<p class="help">Progress is calculated automatically from your tasks.</p>`,data=>mutate('update',data,'Current phase updated.'));break;
    case 'task-add':taskDialog(undefined,id||undefined);break;
    case 'task-edit':taskDialog(id);break;
    case 'rfi-add':rfiDialog();break;
    case 'rfi-edit':rfiDialog(id);break;
    case 'summary-refresh':await refresh();toast('Project summary refreshed.');break;
    case 'up':case 'down': {
      const s=p.sections.find(s=>s.document_ids.includes(id)),pos=s.document_ids.indexOf(id);
      await mutate('arrange',{document_id:id,section_id:s.id,position:pos+(name==='up'?-1:1)},'Document order updated.');break;
    }
    case 'move': {
      const s=p.sections.find(s=>s.document_ids.includes(id));
      modal('Move document',select('Destination section','section_id',p.sections.map(s=>[s.id,s.name]),s.id)+field('Position (1 = first)','position',1,'number','min="1" required'),data=>mutate('arrange',{...data,document_id:id,position:Number(data.position)-1},'Document moved.'));break;
    }
    case 'history': {
      const d=p.documents[id];
      modal(`${d.title} / revisions`,d.revisions.slice().reverse().map(r=>`<div class="record"><div class="toolbar">${pill(r.label)}${link(r.id,'Download original ↗')}</div><div class="note">${esc(r.note)}</div><small>${esc(r.author)} · ${date(r.at)} · ${r.pages||'Attachment'} ${r.pages?'pages':''}</small><p class="help">${r.references.map(ref=>`Uses ${esc(p.documents[ref.document_id].title)} / ${esc(p.documents[ref.document_id].revisions.find(x=>x.id===ref.revision_id)?.label)}`).join('<br>')||'No document dependencies recorded.'}</p><p class="help">SHA-256: ${esc(r.sha256)}</p></div>`).join(''),async()=>{},'Close');break;
    }
    case 'export-project':exportJSON('bigdelta-project-register.json',p);toast('Register exported. Copy the full data folder to back up files too.');break;
    case 'compare-mode':renderComparison(id);break;
    case 'review-save':await saveReview();renderReviewResults();toast('Review decisions saved.');break;
    case 'review-export':await exportReview(element);break;
    case 'review-json':exportJSON('bigdelta-calculation-review.json',reviewSession.job);break;
    case 'review-open':await openReview(id);break;
    case 'review-manual':manualFinding();break;
    case 'review-prev':reviewPage=Math.max(0,reviewPage-1);renderReviewResults();break;
    case 'review-next':reviewPage++;renderReviewResults();break;
  }
}
